import{_ as o,o as r,c as e,ai as p}from"./chunks/framework.scx6l_IK.js";const u=JSON.parse('{"title":"金刚经10分-应无所住生心","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经10分-应无所住生心.md","filePath":"60-原文段落/金刚经10分-应无所住生心.md","lastUpdated":1778155802000}'),a={name:"60-原文段落/金刚经10分-应无所住生心.md"};function _(s,t,n,c,d,i){return r(),e("div",null,[...t[0]||(t[0]=[p('<h1 id="金刚经10分-应无所住生心" tabindex="-1">金刚经10分-应无所住生心 <a class="header-anchor" href="#金刚经10分-应无所住生心" aria-label="Permalink to &quot;金刚经10分-应无所住生心&quot;">​</a></h1><blockquote><p>来源：<a href="/01-Raw-Sources/10了空居士讲《金刚经》-第十分庄严净土分20161104">10了空居士讲《金刚经》-第十分庄严净土分20161104</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>不应住色生心，不应住声香味触法生心</strong></p><p>这个色声香味触法，叫作六尘，六尘是什么意思？尘，就是尘埃的意思，这个就是用这个尘埃来比喻外来的东西，就说菩萨不应该执着这种六尘的现象，产生这种对六尘的贪着或者厌弃这种情绪，这种心啊。</p><p><strong>应无所住而生其心。</strong></p><p>这句话大家听到都会背诵了啊，就是应该无所住，保持这种无所住的心态，而生其心，这句话就是说：你的心对色声香味触法，你不能执着，但是你也会知道，就是心如明镜。譬如你拿个镜子，照一下东西——照到这是一朵花，那是一个人，这里是一棵树啊，等等，但是不管照到什么，你看镜子里面的形象很清楚，但是这个镜嘛，不会受污染，是这个意思。也就是说佛祖告诉我们，我们菩萨的这个心啊，觉悟的人的心啊，就是这样子，他面对着一切情景，他都知道，但是他的心不会产生相应的情绪这种波动。</p><hr><p><strong>庄严佛土者，即非庄严，是名庄严。</strong></p><p>真正去庄严佛国土的人、的菩萨，实非庄严，是名庄严。是名就是说人家看起来菩萨是在庄严佛国土，但是在菩萨心里，他认为做这种事情是一种自然的流露，是一种很正常的事情，他没有说我在庄严，也就是说他没有庄严这种功德相，好像雷锋叔叔他在做这种有限的生命投入到无限的为人民服务中去，他不认为哎呀我今天帮了人，哎呀我功劳很大，他没有啊，他帮助别人就是一种自然地流露，觉得别人需要，他就自觉尽力地去帮助别人，帮助完他也就这么自自然然地走开了。我以前喜欢说帮助别人就像帮助自己一样，他没有这种功德相的执着。所以说，实非庄严，是名庄严。就是他心里没有觉得在庄严佛国土，他觉得这一切都是他自然而然的行为，所以在别人看起来就是在庄严。所以只在名称上就这种行为列为庄严佛国土，但是菩萨他自己没有这种感觉，是本分自然的流露。</p><hr><p><strong>不应住色生心——无私心分别</strong></p><p>譬如说色就是颜色，其实就是形体，这个不应住色生心，譬如说哎呀，明树，这里有一个石头，那里有一堆泥土，那里有一条河，这些有形状的东西都属于色的范畴。那么你这个时候，你看一块大石头和看一块小石头，你的心不要有改变，你就觉得这是一块大石头，这是一块小石头，那里是一条河，那里是一条下水道。你就不要说，哇，这块大石头很好啊，我很喜欢，那个小石头不好看，这条河哎呀，很清澈，这条下水道很脏，我很讨厌。不是，你应该说这条河很清澈，我的心很平静，知道这条河很清澈，这条下水道很脏，我也知道下水道很脏，但是我不要生起厌倦啊什么，我应该生起如何将这条下水道给修好，就是不取不舍，不贪爱，不贪着，也不厌弃，一切都是如实地知道，这就是无所住生心。生心，就是知道，无所住，就是不要产生情绪的波动。</p><p>永嘉玄觉大师有一句很著名的话——这个六祖就问他&quot;仁者自生分别&quot;，然后永嘉大师就回答&quot;分别亦非意&quot;，他说我的分别也不是我特别去起心动念啦，我是如实地看到，如实地知道。你们说无分别心嘛，就是无这个自我的喜欢讨厌的分别心，但是有大公无私的、理智的分别心。譬如你是一个老师，你在看试卷，你不会因为你看到哎呀这个试卷是这个学生的，哎呀我对这个学生印象很好，尽量给他多评几分，那个学生我一看就讨厌，平时调皮捣蛋，哎呀我尽可能给他判少几分，不是，他很客观，对就是对，错就是错，我根本就不管这个试卷是哪个学生的，我只是认真地看他答得对不对，该给多少分我就给多少分。这就是无分别心，不是说什么都不知道啊。</p><p>无分别是这样，也就是无私心分别，我加私心两个字你们就知道了。你们不要以为无分别心就是一塌糊涂，是非对错是没有界限的等等，那么走路你为什么不用两个手去走呢？吃饭为什么不塞到屁股里边去大便从口里吐出来呢？是不是啊？有些学佛的人是学得一团糟，他说以为无分别就什么都不分别，其实无私心分别，真正无分别心的人是怎么样？你该从这个门走出去你就从这个门走出去，下雨该打把雨伞就打把雨伞，晴天不用打雨伞就不打雨伞等等，是这么很客观的，就心如明镜，对一切都了了分明，不以私心来做祟。</p><p><strong>生清净心</strong></p><p>应生其心，就是生起清净心，清净心不是逃避一切现象，而是客观地面对一切现象。</p>',17)])])}const g=o(a,[["render",_]]);export{u as __pageData,g as default};
